/* is_hrule • returns whether a line is a horizontal rule */
static int
is_hrule(uint8_t *data, size_t size)
{
        size_t i = 0, n = 0;
        uint8_t c;

        /* skipping initial spaces */
        if (size < 3) return 0;
        if (data[0] == ' ') { i++;
        if (data[1] == ' ') { i++;
        if (data[2] == ' ') { i++; } } }

        /* looking at the hrule uint8_t */
        if (i + 2 >= size
        || (data[i] != '*' && data[i] != '-' && data[i] != '_'))
                return 0;
        c = data[i];

        /* the whole line must be the char or space */
        while (i < size && data[i] != '\n') {
                if (data[i] == c) n++;
                else if (data[i] != ' ')
                        return 0;

                i++;
        }

        return n >= 3;
}

/* check if a line is a code fence; return the
 * end of the code fence. if passed, width of
 * the fence rule and character will be returned */
static size_t
is_codefence(uint8_t *data, size_t size, size_t *width, uint8_t *chr)
{
        size_t i = 0, n = 1;
        uint8_t c;

        /* skipping initial spaces */
        if (size < 3)
                return 0;

        if (data[0] == ' ') { i++;
        if (data[1] == ' ') { i++;
        if (data[2] == ' ') { i++; } } }

        /* looking at the hrule uint8_t */
        c = data[i];
        if (i + 2 >= size || !(c=='~' || c=='`'))
                return 0;

        /* the fence must be that same character */
        while (++i < size && data[i] == c)
                ++n;

        if (n < 3)
                return 0;

        if (width) *width = n;
        if (chr) *chr = c;
        return i;
}

